    a, b, p = (a - x) / 2, (b - y) / 2, p * 2
  end
  return r
end
local out = {}
for i = 1, #data do
  out[i] = string.char(xor(data[i], key:byte((i - 1) % #key + 1)))
end
local run = (loadstring or load)(table.concat(out))
run()
